beforeEach(() => {
        calls = []
        expectedCalls = []
        wrapper = mount(Treeselect, {
          sync: false,
          propsData: {
            async: true,
            loadOptions({ action, searchQuery, callback }) {
              if (action === 'ASYNC_SEARCH') {
                calls.push(searchQuery)
                callback(null, [ {
                  id: searchQuery,
                  label: searchQuery,
                } ])
              }
            },
          },
        })
        expect(calls).toEqual([])
      })

