                        },
                        bar: 'doBar'
                    }
                },
                doBar: function (s) {
                    // This flavor will work since this is a normal class method
                    this.callParent(arguments);
                    fooResult += 'M2.bar' + s;
                }
            });
            Ext.define('Foo.A', {
                foo: function(s) {
                    fooResult += 'A.foo' + s;
                },
