                    m2: 'Foo.M2'
                },
                foo: function(s) {
                    this.callParent(arguments);
                    fooResult += 'D.foo' + s;
                    return 'D.foo';
                },
                bar: function(s) {
                    this.callParent(arguments);
                    fooResult += 'D.bar' + s;
                    return 42;
                }
            });
            Ext.define('Foo.E', {
                extend: 'Foo.C',
                foo: function(s) {
                    this.callParent(arguments);
                    fooResult += 'B.foo' + s;
