            name: 'Polly.JS'
          }
        }
      };

      class CustomPersister extends Persister {
        static get id() {
          return 'CustomPersister';
        }

        async findRecording() {
          callCounts.find++;
          await timeout(1);

          return recording;
        }

        async saveRecording() {
          callCounts.save++;
          await timeout(1);
        }

        async deleteRecording() {
          callCounts.delete++;
          await timeout(1);
        }
      }

      this.persister = new CustomPersister({});
    })

