beforeEach(() => {
    eventEmitter = new EventEmitter();

    app = express();
    ctxImpl = new CLSContext('zipkin', true);
    const recorder = {record() {}};
    tracer = new Tracer({ctxImpl, recorder});

    app.use(expressMiddleware({tracer}));

    app.get('/', (req, res) => {
      const concurrentRequestStarted = new Promise(resolve => eventEmitter.on('concurrent-request-started', resolve));
      console.log('request-started', tracer.id.traceId);
      eventEmitter.emit('request-started');
      return concurrentRequestStarted.then(() => {
        eventEmitter.emit('request-resumed');
        console.log('request-resumed', tracer.id.traceId);
        res.send(tracer.id.traceId);
      });
    });

    app.get('/concurrent', (req, res) => {
      const requestResumed = new Promise(resolve => eventEmitter.on('request-resumed', resolve));

      console.log('concurrent-request-started', tracer.id.traceId);
      eventEmitter.emit('concurrent-request-started');
      res.send(tracer.id.traceId);
      return requestResumed;
    });
  })

before((done) => {
    const backendApp = express(); // backend is intentionally not traced
    backendApp.get('/weather/wuhan', (req, res) => res.json(req.headers));
    backendApp.get('/weather/bagCity', () => {
      throw new Error('service is dead');
    });
    backend = backendApp.listen(0, () => {
      const frontendApp = express();
      const zipkinProxy = wrapProxy(proxy, {tracer: tracer.tracer(), remoteServiceName});
      frontendApp.use(middleware({tracer: tracer.tracer()}));
      frontendApp.use(zipkinProxy(`127.0.0.1:${backend.address().port}`, {
        decorateRequest: (proxyReq) => {
          tracer.tracer().recordBinary('decorateRequest', '');
          return proxyReq;
        },
        intercept: (rsp, data, serverReq, res, callback) => {
          tracer.tracer().recordBinary('intercept', '');
          callback(null, data);
        }
      }));

      frontend = frontendApp.listen(0, () => {
        baseURL = `http://127.0.0.1:${frontend.address().port}`;
        done();
      });
    });
  })

