            'btRtfFilter': BacktickRtfFilter,
            'rtfFilter': RtfFilter
        };
        // init
        Object.keys(megaChat.plugins).forEach(function(plName) {
            megaChat.plugins[plName] = new megaChat.plugins[plName](megaChat);
        });

        rtf = new RtfFilter(megaChat);
    })

