                    s3.putObjectPromise({
                        Bucket: bucketName,
                        Key: key,
                        Body: 'somebody',
                    })
                );
                queued.push(result);
                return result;
            });
            return Promise.all(putPromises).catch(err => {
                process.stdout.write(`Error creating objects: ${err}\n`);
                throw err;
            });
        });
    })

