            try {
              await browser.bookmarks.removeTree(account.getData().localRoot)
            } catch (e) {
              console.error(e)
            }
            if (ACCOUNT_DATA.type !== 'fake') {
              await account.setData({ ...account.getData(), serverRoot: null })
              const tree = await getAllBookmarks(account)
