  this.timeout(60000)

  shutdownServices = await services()

  browser = shutdownServices.extrasResult.browser
  webpackProcess = shutdownServices.extrasResult.webpackProcess
})

after(async function() {
  if (!isWatchMode) {
    if (browser) {
      await browser.close()
    }
    if (shutdownServices) {
      await shutdownServices()
    }
    if (webpackProcess) {
      webpackProcess.kill()
    }
  }
})

