            'graphql.mutation',
            'graphql.subscription',
            'graphql.parse',
            'graphql.validate',
            'graphql.execute',
            'graphql.field',
            'graphql.resolve'
          ]

          if (a.start.toString() === b.start.toString()) {
            return order.indexOf(a.name) - order.indexOf(b.name)
          }

          return a.start.toString() >= b.start.toString() ? 1 : -1
        })
      })

