beforeEach(() => {
  const sagaMiddleware = createSagaMiddleware();

  store = createStore(
    ({ actionTypes = [] } = {}, { type }) =>
      /^DIRECT_LINE\/(DIS|RE)?CONNECT/u.test(type)
        ? // We are only interested in CONNECT_*, RECONNECT_*, and DISCONNECT_* actions.
          { actionTypes: [...actionTypes, type] }
        : { actionTypes },
    applyMiddleware(sagaMiddleware)
  );

  sagaMiddleware.run(connectSaga);

  directLine = {
    activity$: new Observable(() => () => 0),
    connectionStatus$: new Observable(observer => {
      connectionStatusObserver = observer;
      observer.next(0);
    }),
    end: () => 0,
    postActivity: () =>
      new Observable(observer => {
        observer.next({ id: '' });
      })
  };
})

beforeEach(() => {
  const sagaMiddleware = createSagaMiddleware();

  store = createStore(
    combineReducers({
      actionTypes: (actionTypes = [], { type }) =>
        /^DIRECT_LINE\/(DIS|RE)?CONNECT/u.test(type)
          ? // We are only interested in CONNECT_*, RECONNECT_*, and DISCONNECT_* actions.
            [...actionTypes, type]
          : actionTypes,
      connectivityStatus
    }),
    applyMiddleware(sagaMiddleware)
  );

  sagaMiddleware.run(function*() {
    yield fork(connectSaga);
    yield fork(connectionStatusUpdateSaga);
    yield fork(detectSlowConnectionSaga);
  });

  directLine = {
    activity$: new Observable(() => () => 0),
    connectionStatus$: share(
      new Observable(observer => {
        connectionStatusObserver = observer;
        observer.next(0);
      })
    ),
    end: () => 0,
    postActivity: () =>
      new Observable(observer => {
        observer.next({ id: '' });
      })
  };
})

