	const nextTick = () => new Promise( ( resolve ) => setTimeout( resolve ) );
	if ( jest.isMockFunction( setTimeout ) ) {
		jest.useRealTimers();
		await nextTick();
		jest.useFakeTimers();
	} else {
		await nextTick();
	}
	fetchMock.mockReset();
} )

