beforeEach(() => {
  shallow = new ReactShallowRenderer();
  editorState = EditorState.createEmpty();
})

beforeEach(() => {
  jest.resetModules();
  compositionHandler = require('DraftEditorCompositionHandler');
  editor = {
    _latestEditorState: EditorState.createEmpty(),
    _onCompositionStart: compositionHandler.onCompositionStart,
    _onKeyDown: jest.fn(),
    setMode: jest.fn(),
    restoreEditorDOM: jest.fn(),
    exitCurrentMode: jest.fn(),
    update: jest.fn(state => (editor._latestEditorState = state)),
  };
})

beforeEach(() => {
  Decorator.prototype.getDecorations.mockClear();
  Decorator.prototype.getDecorations.mockImplementation((v, c) => {
    return v === boldBlock ? boldA : List(Repeat(undefined, v.getLength()));
  });
})

beforeEach(() => {
  jest.resetModules();
  forward = DraftRemovableWord.getForward;
  backward = DraftRemovableWord.getBackward;
})

beforeEach(() => {
    applyPatch = sinon.spy()
    context = new Context({[STATE]: { maxOp: 0 }, [CACHE]: {[ROOT_ID]: {}}}, uuid(), applyPatch)
  })

beforeEach(() => {
      listId = uuid()
      list = ['swallow', 'magpie']
      Object.defineProperty(list, OBJECT_ID, {value: listId})
      Object.defineProperty(list, CONFLICTS, {value: [{'1@xxx': 'swallow'}, {'2@xxx': 'magpie'}]})
      Object.defineProperty(list, ELEM_IDS,  {value: ['1@xxx', '2@xxx']})
      context.cache[listId] = list
      context.cache[ROOT_ID] = {[OBJECT_ID]: ROOT_ID, birds: list, [CONFLICTS]: {birds: {'1@actor1': list}}}
    })

beforeEach(() => {
      tableId = uuid()
